"""Migrated Meridian CRM 4.2 order validation rules."""

from decimal import Decimal


_BLOCK = "BLOCK"


def _field(row: dict | None, name: str) -> str:
    """Return a field value, using legacy empty-string behavior for missing fields."""
    if row is None:
        return ""
    return row.get(name, "")


def _numeric(value: object) -> Decimal:
    """Apply legacy numeric coercion: empty string is numeric zero."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: str,
    out_col: str,
) -> str:
    """Implement legacy LOOKUP, including live-row-only visibility."""
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_val:
            return row.get(out_col, "")

    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Validate an order header or order line using legacy rule-file order."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        if event in ("INSERT", "UPDATE"):
            disc_pct = _numeric(_field(record, "DISC_PCT"))
            if not (disc_pct >= 0 and disc_pct <= 100):
                errors.append(
                    {
                        "code": "E5001",
                        "message": "Discount out of range",
                        "severity": _BLOCK,
                    }
                )

        if event == "UPDATE":
            disc_pct = _numeric(_field(record, "DISC_PCT"))
            owner_uid = _field(record, "OWNER_UID")
            role_id = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            if disc_pct > 20 and role_id != "MGR" and role_id != "ADMIN":
                errors.append(
                    {
                        "code": "E5002",
                        "message": "Discount over 20 percent requires manager role",
                        "severity": _BLOCK,
                    }
                )

        if event == "UPDATE":
            old_stat_cd = _field(old, "STAT_CD")
            stat_cd = _field(record, "STAT_CD")
            if old_stat_cd == "I" and stat_cd != "I" and stat_cd != "X":
                errors.append(
                    {
                        "code": "E5003",
                        "message": "Invoiced order can only be cancelled",
                        "severity": _BLOCK,
                    }
                )

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            qty = _numeric(_field(record, "QTY"))
            if not qty > 0:
                errors.append(
                    {
                        "code": "E5004",
                        "message": "Quantity must be positive",
                        "severity": _BLOCK,
                    }
                )

        if event == "INSERT":
            prod_id = _field(record, "PROD_ID")
            active_flg = _lookup(
                tables, "PROD_MASTER", "PROD_ID", prod_id, "ACTIVE_FLG"
            )
            if active_flg != "Y":
                errors.append(
                    {
                        "code": "E5005",
                        "message": "Product not active",
                        "severity": _BLOCK,
                    }
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == _BLOCK for error in errors)
